 '' end) || (CASE WHEN mapping.service_id is null THEN 'service_id is NULL|' else '' end) || (CASE WHEN mapping.network_type is null THEN 'network_type is NULL|' else '' end) || (CASE WHEN mapping.invoicing_company_id is null THEN 'invoicing_company_id is NULL|' else '' end) || (CASE WHEN mapping.share_basis is null THEN 'share_basis is NULL|' else '' end) AS mapping_error ,filter_error ,type_error ,CASE WHEN filter_error IS NOT NULL THEN 'MAN' WHEN type_error IS NOT NULL THEN 'TYP' WHEN dup.chk_duplicate is not null THEN 'DUP' ELSE NULL END AS status ,file_date,workflow_process_date  FROM ( SELECT CASE WHEN TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') IS NULL OR LPAD(TO_CHAR(1), 3, '0') IS NULL OR LPAD(TO_CHAR(ROW_NUMBER() over(ORDER BY NULL)), 9, '0') IS NULL THEN NULL ELSE TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') || LPAD(TO_CHAR(1), 3, '0') || LPAD(TO_CHAR(ROW_NUMBER() over(ORDER BY NULL)), 9, '0') END AS cdr_id ,partner ,owner ,iccid ,CASE WHEN REGEXP_LIKE(SUBSTR(first_installed, 1, 14), '^[0-9]{14}$') THEN TO_TIMESTAMP(SUBSTR(first_installed, 1, 14) DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDDHH24MISS') END first_installed ,profile_type ,eid ,sim_type ,'1' cdr_type ,input_source_name AS cdr_filename ,chk_duplicate ,filter_dtm ,b_no ,(CASE WHEN partner is null THEN 'partner is NULL|' else '' end) || (CASE WHEN owner is null THEN 'owner is NULL|' else '' end) || (CASE WHEN iccid is null THEN 'iccid is NULL|' else '' end) || (CASE WHEN first_installed is null THEN 'first_installed is NULL|' else '' end) || (CASE WHEN profile_type is null THEN 'profile_type is NULL|' else '' end) || (CASE WHEN sim_type is null THEN 'sim_type is NULL|' else '' end) AS filter_error ,(CASE WHEN CASE WHEN REGEXP_LIKE(SUBSTR(first_installed, 1, 14), '^[0-9]{14}$') THEN TO_TIMESTAMP(SUBSTR(first_installed, 1, 14) DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDDHH24MISS') END is null THEN 'first_installed: Invalid TIMESTAMP type (Raw=' || first_installed || ')|' else '' end) AS type_error ,file_date FROM ( SELECT partner partner ,owner owner ,iccid iccid ,first_installed first_installed ,profile_type profile_type ,eid eid ,sim_type sim_type ,process_date AS filter_dtm ,CASE WHEN partner IS NULL OR sim_type IS NULL THEN NULL ELSE partner || '_ESIM_' || sim_type END AS b_no ,REPLACE(REGEXP_SUBSTR(REGEXP_SUBSTR(input_source_name, '[^/]+$'), '(.+)(_)([0-9]{8}_[0-9]{6})(_)(.+[.].+)', 1, 1, 'c', 3), '_', '') AS file_date ,input_source_name ,coalesce(iccid,'') AS chk_duplicate FROM <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.tb_landing_ss_esim WHERE  body_tag='02' and partition_minute BETWEEN ( SELECT MIN(checkpoint_partition) FROM <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.tb_staging_ss_esim_checkpoint_temp) AND ( SELECT MAX(checkpoint_partition) FROM <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.tb_staging_ss_esim_checkpoint_temp) AND partition_minute > ( SELECT coalesce(MAX(checkpoint_partition),0) FROM <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.tb_staging_ss_esim_checkpoint) ) ) raw_ CROSS JOIN ( SELECT workflow_process_date FROM <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.tb_staging_ss_esim_landing_to_discovery_workflow_status ) JOIN ( SELECT cdr_type ,source_path FROM <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.ext_dss_tb_master_cdr_type WHERE record_status = 'A' ) cdr_mas ON raw_.cdr_type = cdr_mas.cdr_type LEFT JOIN ( SELECT chk_duplicate FROM <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.tb_transaction_ss_esim_valid UNION SELECT chk_duplicate FROM <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.tb_transaction_ss_esim_temp ) dup ON raw_.chk_duplicate = dup.chk_duplicate LEFT JOIN ( SELECT distinct b_no AS b_no ,content_partner_id AS cp_id ,service_id AS service_id ,network_type AS network_type ,share_basis AS share_basis ,invoicing_company_id AS invoicing_company_id ,TRUNC(effective_date) AS effective_date ,TRUNC(expired_date) AS expired_date ,price_rate_type AS price_rate_type FROM <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.ext_dss_vw_service_mapping_bno_key WH